#include "dsky_octal_verb_check.h"
#include "dsky_octal_verb_vectors.h"
uint8_t dsky_octal_verb_checkpoint_input(uint8_t n,apollo_overlay_state *s,p66_bias_io *io,enum dsky_nv_mission *mission,uint8_t *entry){if(n>=128u)return 0;dsky_octal_verb_input(s,io,dsky_octal_verb_numbers[n],mission,entry);return 1;}
uint16_t dsky_octal_verb_checkpoint(uint8_t n,apollo_overlay_state *s,apollo_overlay_state *before){p66_bias_io io,old;enum dsky_nv_mission mission;uint8_t entry;enum dsky_octal_verb_route route;uint16_t f,p,end,failures=0;if(!dsky_octal_verb_checkpoint_input(n,s,&io,&mission,&entry))return 1;*before=*s;old=io;if((entry==2u?dsky_octal_verb_channel(s,&io,mission,s->words[01020],&route):entry?dsky_octal_verb_return(s,&io,mission,&route):dsky_octal_verb_begin(s,&io,mission,&route))!=P66_BIAS_OK)++failures;p=dsky_octal_verb_after_offsets[n];end=dsky_octal_verb_after_offsets[n+1u];for(f=0;f<2050u;++f){uint16_t expected=f<2048u?before->words[f]:f==2048u?old.superbank:old.interrupt_enabled;uint16_t actual=f<2048u?s->words[f]:f==2048u?io.superbank:io.interrupt_enabled;if(p<end&&dsky_octal_verb_after_patch[p][0]==f)expected=dsky_octal_verb_after_patch[p++][1];if(actual!=expected)++failures;}if(p!=end)++failures;return failures;}
